/**
 * bridge-checks: shows CI builds in Gerrit's Checks tab.
 *
 * Generated by the GitHub bridge (internal/gerritchecks); install it as
 * $site/plugins/bridge-checks.js. The runs come from the bridge's
 * /checks endpoint, which reads them from Buildkite.
 */
const BRIDGE_URL = "__BRIDGE_URL__";
const PROJECT = "__PROJECT__";
const RETEST = 'retest';

function toDates(run) {
  for (const k of ['scheduledTimestamp', 'startedTimestamp', 'finishedTimestamp']) {
    if (run[k]) run[k] = new Date(run[k]);
  }
  return run;
}

window.Gerrit.install(plugin => {
  // Rerun posts "retest" as the signed-in user, exactly as typing it
  // would: CI decides whether that user may start a build.
  const retest = async (change, patchset) => {
    try {
      await plugin.restApi().post(
          `/changes/${change}/revisions/${patchset}/review`, {message: RETEST});
      return {message: 'Asked CI to build this patch set again (retest).', shouldReload: true};
    } catch (e) {
      return {errorMessage: `Could not post "retest": ${e}`};
    }
  };
  const rerun = {
    name: 'Rerun',
    tooltip: 'Comment "retest" so CI builds this patch set again',
    primary: true,
    callback: retest,
  };

  plugin.checks().register({
    fetch: async data => {
      if (data.repo !== PROJECT) return {responseCode: 'OK', runs: []};
      let resp;
      try {
        resp = await fetch(`${BRIDGE_URL}/checks/${data.changeNumber}/${data.patchsetNumber}`);
      } catch (e) {
        return {responseCode: 'ERROR', errorMessage: `Cannot reach the bridge at ${BRIDGE_URL} (${e})`};
      }
      if (resp.status === 404) return {responseCode: 'OK', runs: []};
      if (!resp.ok) {
        let msg = `${resp.status}`;
        try { msg = (await resp.json()).error || msg; } catch (e) {}
        return {responseCode: 'ERROR', errorMessage: `CI results unavailable: ${msg}`};
      }
      const body = await resp.json();
      const runs = (body.runs || []).map(toDates);
      for (const run of runs) {
        if (run.status === 'COMPLETED') run.actions = [rerun];
      }
      return {
        responseCode: 'OK',
        runs,
        links: body.links || [],
        actions: [{...rerun, name: 'Rerun CI', primary: false}],
      };
    },
  }, {fetchPollingIntervalSeconds: 30});
});
